using FluentValidation; using InventorySystem.Application.Commands; namespace InventorySystem.Application.Validators; public sealed class CreatePersonnelCommandValidator:AbstractValidator<CreatePersonnelCommand>{public CreatePersonnelCommandValidator(){RuleFor(x=>x.SicilNo).NotEmpty().MaximumLength(50);RuleFor(x=>x.Ad).NotEmpty().MaximumLength(100);RuleFor(x=>x.Soyad).NotEmpty().MaximumLength(100);RuleFor(x=>x.Departman).NotEmpty().MaximumLength(120);RuleFor(x=>x.Pozisyon).NotEmpty().MaximumLength(120);RuleFor(x=>x.Eposta).EmailAddress().When(x=>!string.IsNullOrWhiteSpace(x.Eposta)).MaximumLength(200);RuleFor(x=>x.ZimmetNo).MaximumLength(50);}} public sealed class UpdatePersonnelCommandValidator:AbstractValidator<UpdatePersonnelCommand>{public UpdatePersonnelCommandValidator(){RuleFor(x=>x.Id).NotEmpty();RuleFor(x=>x.SicilNo).NotEmpty().MaximumLength(50);RuleFor(x=>x.Ad).NotEmpty().MaximumLength(100);RuleFor(x=>x.Soyad).NotEmpty().MaximumLength(100);RuleFor(x=>x.Departman).NotEmpty().MaximumLength(120);RuleFor(x=>x.Pozisyon).NotEmpty().MaximumLength(120);RuleFor(x=>x.Eposta).EmailAddress().When(x=>!string.IsNullOrWhiteSpace(x.Eposta)).MaximumLength(200);RuleFor(x=>x.ZimmetNo).MaximumLength(50);}} public sealed class DeletePersonnelCommandValidator:AbstractValidator<DeletePersonnelCommand>{public DeletePersonnelCommandValidator(){RuleFor(x=>x.Id).NotEmpty();}}
